/** `caitlyn.core.documents`. */
export interface CoreDocumentsNamespace {
  /** Redirects to a short-lived address for a document's bytes, for links and command-line tools.
   * 
   * Answers 302, with `Location` the address, which works for 15 minutes and needs no credential, so
   * treat it as a secret. Without `version`, the current version's bytes. Use it as a link's target,
   * or with `curl -L`. A browser script cannot read a redirect's address: it calls
   * GetDocumentDownload, which answers with the address as JSON, as the SDKs' `doc.download()` does. */
  content(knowledgeBaseId: string, documentId: string, input?: Omit<GetDocumentContentInput, "knowledgeBaseId" | "documentId">, options?: CallOptions): ReturnType<typeof ops.getDocumentContent>;
}

/** `caitlyn.core.ingestion`. */
export interface CoreIngestionNamespace {
  /** Reports that items' bytes are in place, so they can be ingested.
   * 
   * Takes 1 to 100 item identifiers, each awaiting upload. For each, the server checks that the
   * uploaded object's stored SHA-256 and size match the item's, and that the caller may still write to
   * the item's folder, then starts its ingestion. Returns 200 with a result for each item, in request
   * order: `accepted`, or `failed` with `CHECKSUM_MISMATCH` (the object is deleted; upload it again),
   * `NOT_FOUND` (nothing was uploaded to the item's key), `PERMISSION_DENIED`, `UPLOAD_EXPIRED` or
   * `CONFLICT` (the item is not awaiting upload). One failed item never stops the others. The SDKs
   * always call this for you. An upload nobody reports is found by the server within about a minute,
   * while the batch has items awaiting upload, and goes through the same checks; only an item whose
   * bytes are still missing when its reservation ends fails, with `UPLOAD_EXPIRED`. */
  completeUploads(knowledgeBaseId: string, ingestionBatchId: string, itemIds: CompleteIngestionBatchUploadsInput["itemIds"], options?: CallOptions): ReturnType<typeof ops.completeIngestionBatchUploads>;
  /** Renews a running batch's upload policy before it expires.
   * 
   * Returns a new policy for the same key prefix while the batch is `running` and has items awaiting
   * upload; anything else is refused with 409 `CONFLICT`. Each renewal also extends how long the
   * batch's new documents stay reserved. A renewed policy lasts the batch's `uploadWindowSeconds`, as the
   * first did. The SDKs renew when less than 5 minutes, or half the policy's lifetime when that is
   * shorter, are left. */
  uploadPolicy(knowledgeBaseId: string, ingestionBatchId: string, options?: CallOptions & { idempotencyKey?: string }): ReturnType<typeof ops.createIngestionBatchUploadPolicy>;
  /** Adds up to 10,000 more items to a batch that is still `draft`, with a result for each.
   * 
   * A batch takes at most 100,000 items, at most 1,000 of them with `fetchUrl`. The call returns 200
   * even when every item fails: `results` has one entry per item, in request order, each `created` with
   * the item, or `failed` with a problem (for example 422 `BATCH_ITEM_CONTENT_AMBIGUOUS`). One bad
   * item never refuses the rest. A batch that is not `draft` is refused with 409 `CONFLICT`. */
  addItems(knowledgeBaseId: string, ingestionBatchId: string, items: BatchCreateIngestionBatchItemsInput["items"], input?: Omit<BatchCreateIngestionBatchItemsInput, "knowledgeBaseId" | "ingestionBatchId" | "items">, options?: CallOptions): ReturnType<typeof ops.batchCreateIngestionBatchItems>;
}

/** `caitlyn.core.operations`: call it with the identifiers for one thing's scope; its methods act on the collection. */
export interface CoreOperationsCollection {
  (knowledgeBaseId: string, operationId: string): CoreOperationScope;
  /** Lists the Operations on one knowledge base, or one thing in it, newest first.
   * 
   * The caller needs read access to the knowledge base. Narrow the list with the target, the kind and
   * the status. */
  list(knowledgeBaseId: string, input?: Omit<ListOperationsInput, "knowledgeBaseId">, options?: CallOptions): ReturnType<typeof ops.listOperations>;
}

/** `caitlyn.core.operations(knowledgeBaseId, operationId)`: a scope; making it sends nothing. */
export interface CoreOperationScope {
  readonly knowledgeBaseId: string;
  readonly operationId: string;
  /** Gets one Operation: where its work is, how far it has got, and how it ended.
   * 
   * The caller needs the access it would need to read the Operation's target; anyone else gets 404.
   * Everyday code waits through the scope the work is on (`doc.wait()`, `kb.wait()`) instead. */
  get(options?: CallOptions): ReturnType<typeof ops.getOperation>;
  /** Cancels an Operation's work.
   * 
   * Work not started yet is dropped; work running is stopped where its kind allows. Only
   * `document_ingestion` can be cancelled today: a cancelled first version removes the document, and a
   * cancelled new version leaves the current one serving. Any other kind is refused with 409
   * `OPERATION_NOT_CANCELLABLE`, and a final Operation with 409 `CONFLICT`. Returns the Operation, which
   * becomes `cancelled` once the work has stopped.
   * 
   * Cancelling needs what starting that kind of work needs, on the same record, which the server
   * reads from the Operation and checks per kind before it acts: for `document_ingestion`, the
   * permission that started it (`files.create` for a new document, `files.update` for a new version
   * or a retry) and the document's readers; for `document_update`, `files.update` and its readers; for
   * `fill_in`, `reprocess` and `layout_aware_search`, `knowledge-bases.update` and
   * `knowledge-bases.ingestions.update`; for a `folder_change`, the permission of the change
   * (`files.create`, `files.update` or `files.delete`) and the folder's readers; for
   * `permissions_change`, `files.permissions.update` and the record's readers; for
   * `knowledge_base_deletion`, `knowledge-bases.delete`. A caller without it gets 404, as for an
   * Operation it may not see. No one permission is common to every kind, so the operation declares
   * only what reading an Operation needs (`files.read`, as GetOperation), and the per-kind check does
   * the rest. */
  cancel(options?: CallOptions): ReturnType<typeof ops.cancelOperation>;
  /** Watches an Operation: the whole Operation each time it changes, ending when it is final.
   * 
   * The stream sends `operation.updated` on each change and ends with `operation.finished`. With
   * `Last-Event-ID`, a dropped connection resumes without losing a change. */
  watch(input?: Omit<WatchOperationInput, "knowledgeBaseId" | "operationId">, options?: CallOptions): ReturnType<typeof ops.watchOperation>;
}

/** `caitlyn.core.uploads`: call it with an identifier for one thing's scope; its methods act on the collection. */
export interface CoreUploadsCollection {
  (uploadId: string): CoreUploadScope;
  /** Reserves a short-lived slot for a file's bytes and returns a presigned URL bound to their
   * checksum.
   * 
   * Send the bytes with `uploadMethod` to `uploadUrl`, with every header in `requiredHeaders`,
   * before `expiresAt`; then pass the upload's `id` to the operation that uses it. Files can be at
   * most 2 GB. For an attachment, name the conversation in `purpose`: the conversation's attachment
   * settings are checked here, before the bytes travel. The SDKs' `core.uploads.send(file)` does all of
   * this, and their document and attachment helpers call it for you. Many files at once go through an
   * ingestion batch instead, which signs one upload policy for them all. */
  reserve(input: Omit<CreateUploadInput, "idempotencyKey">, options?: CallOptions & { idempotencyKey?: string }): ReturnType<typeof ops.createUpload>;
  /** Sends a file (PROTOCOL.md 14): hashes it, reserves an upload, PUTs the bytes, and returns the upload, whose `id` an operation that takes an upload uses. */
  send(file: FileInput, input?: Parameters<typeof ops.sendUpload>[2], options?: Parameters<typeof ops.sendUpload>[3]): ReturnType<typeof ops.sendUpload>;
}

/** `caitlyn.core.uploads(uploadId)`: a scope; making it sends nothing. */
export interface CoreUploadScope {
  readonly uploadId: string;
  /** Gets an upload's status and when its upload URL expires.
   * 
   * Use it to check that the bytes arrived before passing the upload's `id` to the operation that
   * uses it. Only the person or client that reserved the upload can read it; anyone else gets 404. */
  get(options?: CallOptions): ReturnType<typeof ops.getUpload>;
}

/** How `caitlyn.knowledgeBases(knowledgeBaseId).ingestion.batches(ingestionBatchId)` is waited on: its watch, and its get. */
function specKnowledgeBaseIngestionBatchScope(c: CaitlynClient, ids: Ids): WaitSpec<Out<IngestionBatch>> {
  return {
    watch: (signal: AbortSignal) => watchKnowledgeBaseIngestionBatchScope(c, ids, { signal }) as AsyncIterable<Record<string, any>>,
    kind: "batch",
    id: ids.ingestionBatchId,
    get: (signal: AbortSignal) => ops.getIngestionBatch(c, { knowledgeBaseId: ids.knowledgeBaseId, ingestionBatchId: ids.ingestionBatchId } as Parameters<typeof ops.getIngestionBatch>[1], { signal }),
    toError,
    jobError,
  };
}

/** `caitlyn.knowledgeBases(knowledgeBaseId).ingestion.batches(ingestionBatchId)`'s watch, which reads it again once its deadline has passed (PROTOCOL.md 16). */
function watchKnowledgeBaseIngestionBatchScope(c: CaitlynClient, ids: Ids, options?: CallOptions) {
  return rereadAtDeadline(ops.watchKnowledgeBase(c, { knowledgeBaseId: ids.knowledgeBaseId, batch: ids.ingestionBatchId } as Parameters<typeof ops.watchKnowledgeBase>[1], options), (signal: AbortSignal) => ops.getIngestionBatch(c, { knowledgeBaseId: ids.knowledgeBaseId, ingestionBatchId: ids.ingestionBatchId } as Parameters<typeof ops.getIngestionBatch>[1], { signal }), options);
}

