/** The Caitlyn client: every operation, as scopes (`caitlyn.knowledgeBases(id).documents.create(file)`). */
export class Caitlyn {
  readonly client: CaitlynClient;
  /** The sign-in session: the current token, and the oauth mode's authorizationUrl(), handleCallback() and signOut(). */
  readonly auth: AuthSession;
  readonly agents: AgentsCollection;
  readonly conversations: ConversationsCollection;
  readonly events: EventsScope;
  readonly knowledgeBases: KnowledgeBasesCollection;
  readonly core: CoreNamespace;

  constructor(options: CaitlynOptions) {
    this.auth = createAuth(options);
    this.client = createCaitlynClient(options, this.auth);
    const c = this.client;
    this.agents = makeAgentsCollection(c, {});
    this.conversations = makeConversationsCollection(c, {});
    this.events = makeEventsScope(c, {});
    this.knowledgeBases = makeKnowledgeBasesCollection(c, {});
    this.core = makeCoreNamespace(c, {});
  }

  /** Describes the caller: who the credential belongs to, what kind of credential it is, its scopes
   * and its organisation.
   * 
   * Any valid credential may call it, with no particular scope, so an integration can check its
   * credential before doing anything else. It only describes the credential that made the request;
   * it never reads another person's or client's record. */
  me(options?: CallOptions): ReturnType<typeof ops.getCaller> {
    const c = this.client;
    return ops.getCaller(c, {  } as Parameters<typeof ops.getCaller>[1], options);
  }
}
